import{_ as p,C as e,o as d,c,j as r,a as t,G as n,a2 as s}from"./chunks/framework.BgSoyxN5.js";const w=JSON.parse('{"title":"Что TickerForge даёт партнёру | Доступ, контент, отслеживание ссылок, реферальные выплаты","description":"Вторая половина партнёрского обмена: доступ к продукту, готовый контент для публикаций, отслеживаемые ссылки, отчётность и правила расчёта реферального вознаграждения.","frontmatter":{"title":"Что TickerForge даёт партнёру | Доступ, контент, отслеживание ссылок, реферальные выплаты","description":"Вторая половина партнёрского обмена: доступ к продукту, готовый контент для публикаций, отслеживаемые ссылки, отчётность и правила расчёта реферального вознаграждения.","aside":false,"locale":"ru","alternateLocales":{"en":"/partners/what-you-get","ru":"/ru/partners/what-you-get"},"pageClass":"partners-page"},"headers":[],"relativePath":"ru/partners/what-you-get.md","filePath":"ru/partners/what-you-get.md","lastUpdated":1788362384000}'),g={name:"ru/partners/what-you-get.md"},u={class:"partners-wide"};function h(f,a,m,_,b,k){const i=e("PartnerPageAnalytics"),l=e("PartnerReferralCta"),o=e("PartnerLeadForm");return d(),c("div",null,[a[0]||(a[0]=r("h1",{id:"что-мы-даем-партнеру",tabindex:"-1"},[t("Что мы даём партнёру "),r("a",{class:"header-anchor",href:"#что-мы-даем-партнеру","aria-label":'Permalink to "Что мы даём партнёру"'},"​")],-1)),a[1]||(a[1]=r("p",null,[r("a",{href:"/ru/partners/requirements"},"Требования к партнёрам"),t(" описывают, что мы просим от партнёра. Эта страница — вторая половина обмена: что TickerForge обязуется дать взамен, теми же прямыми словами.")],-1)),a[2]||(a[2]=r("p",null,"Ничего из перечисленного не зависит от результата. Всё это начинает работать в день одобрения пилота и действует весь срок пилота.",-1)),n(i,{offer:"what_you_get",locale:"ru"}),a[3]||(a[3]=s('<div class="partners-hero-actions"><a class="partners-button partners-button--primary" href="#apply" data-partner-event="cta" data-partner-option="propose_pilot" data-analytics-placement="partner_hero">Подать заявку на пилот</a><a class="partners-button partners-button--secondary" href="#rewards" data-partner-event="cta" data-partner-option="rewards" data-analytics-placement="partner_hero">Как считается вознаграждение</a></div><p class="partners-locale-switch"><a href="/partners/what-you-get" hreflang="en" data-partner-event="cta" data-partner-option="locale_en" data-analytics-placement="partner_locale_switch">Read this page in English</a></p><p class="partners-backlink"><a href="/ru/partners">Ко всем вариантам партнёрства</a> · <a href="/ru/partners/requirements">Требования к партнёрам</a> · <a href="/ru/partners/cabinet">Partner Cabinet</a> · <a href="/ru/partners/stock-analysis-and-ideas">Исследования в Telegram</a> · <a href="/ru/partners/market-news">Рыночные новости</a></p><p>TickerForge — образовательное программное обеспечение для поддержки решений. Это не инвестиционная рекомендация, не сигнальный канал, не брокер и не обещание доходности.</p><h2 id="access" tabindex="-1">⭐ Доступ Standard на весь срок пилота <a class="header-anchor" href="#access" aria-label="Permalink to &quot;⭐ Доступ Standard на весь срок пилота {#access}&quot;">​</a></h2><p>Одобренный пилот переводит ваш аккаунт TickerForge на Standard на весь срок пилота. Именно поэтому партнёрские посты имеет смысл публиковать: они собираются из полного слоя исследований, а не из бесплатного публичного превью.</p><div class="partners-wide partners-wide--compact"><ul class="partners-feature-list"><li><strong>Скринеры без бесплатного потолка.</strong> Диапазон оценки TickerForge открывается полностью, а не обрезается на публичном пороге.</li><li><strong>Повышенные лимиты Smart Alerts и отслеживания.</strong> Больше отслеживаемых компаний, больше подписок на алерты.</li><li><strong>Портфельные отчёты и диагностика уровня Standard.</strong></li><li><strong>Workspace на сайте показывает <em>Partner pilot</em></strong> вместо Free — продукт ведёт себя одинаково и в боте, и на сайте.</li></ul></div><p>Доступ выдаётся по одобрению, а не по оплате. Это не покупка: в наших отчётах он не делает вас платящим подписчиком и не занимает место в когорте Early Access.</p><h2 id="content" tabindex="-1">🧠 Контент, который можно опубликовать в тот же день <a class="header-anchor" href="#content" aria-label="Permalink to &quot;🧠 Контент, который можно опубликовать в тот же день {#content}&quot;">​</a></h2><p>У каждого направления есть свой список форматов — тех, что уже работают в Partner Cabinet, и тех, что готовятся под пилот по запросу. Актуальные списки живут на трёх страницах направлений:</p><div class="partners-wide"><div class="partners-format-grid"><div class="partners-format partners-format--linked"><span>Направление</span><strong><a href="/ru/partners/stock-analysis-and-ideas">Исследования в Telegram</a></strong><p>Исследования по компаниям: вердикт по акции, активность инсайдеров, движения фондов и еженедельные рубрики.</p></div><div class="partners-format partners-format--linked"><span>Направление</span><strong><a href="/ru/partners/market-news">Рыночные новости</a></strong><p>Регулярный рыночный и макро-контекст: рыночный режим, алерт о его смене и экономическое здоровье США.</p></div><div class="partners-format partners-format--linked"><span>Направление</span><strong><a href="/ru/partners/portfolio-health">Здоровье портфеля</a></strong><p>Контент по диагностике портфеля — готовится под конкретный пилот, а не генерируется одной кнопкой.</p></div></div></div><p>Что мы гарантируем по этому контенту:</p><div class="partners-wide partners-wide--compact"><ul class="partners-feature-list"><li><strong>Реальные данные, генерация по запросу.</strong> Пост — это живой экран продукта на момент нажатия кнопки, а не шаблон с подставленным тикером.</li><li><strong>Тот же пост, что выходит в канале.</strong> С форматированием и картинкой — его можно переслать как есть.</li><li><strong>Честный отказ.</strong> Если данных для поста нет, кабинет прямо говорит об этом и ничего не генерирует. Алерт о смене режима, например, существует только в те недели, когда режим действительно повернул: вам никогда не выдадут пост о смене, которой не было.</li><li><strong>Одна рубричная идея в неделю резервируется за вами</strong> — двум партнёрам не выдадут одну и ту же компанию на одной неделе.</li></ul></div><h2 id="language" tabindex="-1">🌐 Посты на языке вашей аудитории <a class="header-anchor" href="#language" aria-label="Permalink to &quot;🌐 Посты на языке вашей аудитории {#language}&quot;">​</a></h2><p>В Partner Cabinet, в разделе <strong>Generate Post</strong>, есть переключатель English / Русский. Он меняет пост целиком, а не только кнопку под ним, и работает для всех форматов. Сам кабинет в обоих случаях остаётся на английском — настройка про то, что получают ваши читатели.</p><h2 id="tracking" tabindex="-1">🔗 Отслеживаемые ссылки и привязка читателя <a class="header-anchor" href="#tracking" aria-label="Permalink to &quot;🔗 Отслеживаемые ссылки и привязка читателя {#tracking}&quot;">​</a></h2><div class="partners-wide partners-wide--compact"><ul class="partners-feature-list"><li><strong>Каждый сгенерированный пост уже несёт вашу ссылку</strong> — внутри собственного призыва к действию. Ничего вставлять и настраивать не нужно.</li><li><strong>Ссылка открывает бота, а не промежуточную страницу.</strong> Читатель попадает сразу в нужный сценарий TickerForge: карточку акции, рыночную панель, меню экономики США.</li><li><strong>Персональный реферальный код и ссылка</strong> выдаются автоматически при одобрении пилота. Это вторая, отдельная ссылка — для описания канала, сторис или комментария: сгенерированные посты привязывают читателей и без неё.</li><li><strong>Привязка по первому касанию.</strong> Читатель, пришедший с вашего поста, закрепляется за вами и остаётся закреплённым.</li></ul></div><h2 id="rewards" tabindex="-1">💰 Реферальное вознаграждение <a class="header-anchor" href="#rewards" aria-label="Permalink to &quot;💰 Реферальное вознаграждение {#rewards}&quot;">​</a></h2><p>Читатели, привязанные через партнёрские ссылки, попадают в существующую реферальную программу TickerForge и зарабатывают ровно по тем же правилам, что и в <a href="/ambassador">/ambassador</a> — партнёрская программа не вводит отдельную ставку.</p><div class="partners-wide partners-wide--compact"><ul class="partners-feature-list"><li><strong>20% от подписки приведённого пользователя каждый месяц</strong>, пока эта подписка активна. Ограничений по числу рефералов и по сумме в месяц нет.</li><li><strong>Расчёт по календарному месяцу</strong> — по тем платным планам, которые ваши рефералы держали в этом месяце.</li><li><strong>Оплата идёт в Telegram Stars.</strong> Планы тарифицируются в Stars; суммы в долларах на <a href="/pricing">странице тарифов</a> — это ориентир, а не второй прайс-лист.</li><li><strong>Видно до выплаты.</strong> <em>My Monthly Earnings</em> в боте — живая оценка по текущему состоянию подписок: рабочая цифра, а не выставленный счёт.</li><li><strong>Порядок выплат согласуется индивидуально</strong>, когда появятся первые платящие рефералы. Условия можно уточнить заранее — через бота или <a href="/contact">напишите нам</a>.</li></ul></div><p class="partners-fineprint">Вознаграждение зависит от того, сколько приведённых пользователей держат активный платный план в конкретном месяце. Ничего из написанного не является прогнозом заработка канала.</p><h2 id="reporting" tabindex="-1">📊 Цифры, которые мы отдаём обратно <a class="header-anchor" href="#reporting" aria-label="Permalink to &quot;📊 Цифры, которые мы отдаём обратно {#reporting}&quot;">​</a></h2><p>Пилот имеет смысл только если обе стороны видят, сработал он или нет. Внутри Partner Cabinet:</p><div class="partners-wide partners-wide--compact"><ul class="partners-feature-list"><li><strong>Статистика</strong> — приведённые пользователи, активные платящие рефералы за месяц, оценка выплаты и разбивка по типам постов.</li><li><strong>Запуски бота по типам постов</strong> — сколько читателей реально открыли TickerForge с каждого формата. Видно, на что откликается именно ваша аудитория.</li><li><strong>Месячный отчёт</strong> — текущий или предыдущий месяц выгрузкой в XLSX, по запросу.</li><li><strong>My Progress</strong> — статус, срок доступа, сгенерированные и подтверждённые посты.</li></ul></div><h2 id="not-included" tabindex="-1">Что не входит автоматически <a class="header-anchor" href="#not-included" aria-label="Permalink to &quot;Что не входит автоматически {#not-included}&quot;">​</a></h2><p>Одобренный пилот даёт доступ Standard и ничего сверх него. Pro-доступ, массовый API или сырые данные, кастомные и white-label отчёты, ко-брендовые лендинги, платные размещения и эксклюзив в нише — это отдельные коммерческие разговоры, и каждый из них проще обосновать, когда за первым пилотом уже стоят реальные цифры. Полный список — в <a href="/ru/partners/requirements#not-included">Требованиях к партнёрам</a>.</p>',26)),n(l),a[4]||(a[4]=r("h2",{id:"apply",tabindex:"-1"},[t("Подать заявку на пилот "),r("a",{class:"header-anchor",href:"#apply","aria-label":'Permalink to "Подать заявку на пилот {#apply}"'},"​")],-1)),a[5]||(a[5]=r("p",null,"Расскажите о канале и о пилоте, который хотите запустить: ссылка на канал или сообщество, размер аудитории и типичные охваты, язык, основная тема, нужное направление и идея первого поста.",-1)),r("div",u,[n(o,{source:"partners_what_you_get"})]),a[6]||(a[6]=s('<h2 id="смежные-страницы" tabindex="-1">Смежные страницы <a class="header-anchor" href="#смежные-страницы" aria-label="Permalink to &quot;Смежные страницы&quot;">​</a></h2><ul><li><a href="/ru/partners">Все варианты партнёрства</a></li><li><a href="/ru/partners/requirements">Требования к партнёрам — что просим мы</a></li><li><a href="/ru/partners/cabinet">Как работает Partner Cabinet</a></li><li><a href="/ru/partners/stock-analysis-and-ideas">Партнёры-исследователи в Telegram</a></li><li><a href="/ru/partners/market-news">Партнёры по рыночным новостям</a></li><li><a href="/ru/partners/portfolio-health">Партнёры по здоровью портфеля</a></li><li><a href="/ambassador">Ambassador / реферальная программа</a></li><li><a href="/pricing">Тарифы TickerForge</a></li></ul>',2))])}const v=p(g,[["render",h]]);export{w as __pageData,v as default};
